  // `sinks` array on the envelope overrides it. See shared/conversation.js.
  PubSub.subscribe('CONVERSATION.PROMPT', (msg, data) => {
    const turn = normalizeTurn(data, { role: ROLE.USER, subTopic: subTopicOf(msg) });

    if (!turn.text) {
      console.warn('[AppEvents] CONVERSATION.PROMPT received without text', data);
      return;
    }

    // turnId is logged so a duplicated delivery is distinguishable from a
    // duplicated send: same id means one publish reached us twice, different
    // ids mean two publishes were made.
    console.log(`[AppEvents] PROMPT ${turn.sinks.join('+')} [${turn.source}] ${turn.turnId}:`, turn.text);

    if (turn.sinks.includes(SINK.STAGE)) {
      // Stage the text in the prompt area for the user to edit before sending.
      const promptArea = document.querySelector('m5t-chat-prompt-area');
      if (promptArea?.setMessage) promptArea.setMessage(turn.text);
      else console.warn('[AppEvents] STAGE sink: no m5t-chat-prompt-area on this route');
    }

    if (turn.sinks.includes(SINK.CANVAS)) {
      renderTurn(turn);
      PubSub.publish(AppBroadcast.CANVAS_DO_SCROLL);
    }

    if (turn.sinks.includes(SINK.AGENT)) {
      // Commands are intercepted for every agent-bound prompt, not just the
      // AGENT_CANVAS leaf, so `::` behaves the same however it was published.
      if (isCommand(turn.text)) runCommand(turn);
      else routeThenPrompt(turn);
    }
  });

  PubSub.subscribe('CONVERSATION.RESPONSE', (msg, data) => {
    const turn = normalizeTurn(data, { role: ROLE.ASSISTANT, subTopic: subTopicOf(msg) });

    // A waiting turn carries no text on purpose - the phrases live in
    // <m5t-chat-waiting>, not the envelope - so it is exempt from the
    // empty-delta guard, which exists to catch malformed publishes.
    if (!turn.text && turn.phase !== PHASE.END && !turn.meta?.waiting) {
      console.warn('[AppEvents] CONVERSATION.RESPONSE received without text', data);
      return;
    }

    if (turn.sinks.includes(SINK.CANVAS)) renderTurn(turn);

    if (turn.sinks.includes(SINK.WORKFLOW)) runWorkflow(turn);
  });

